        return image_patch

    tv_centers = [(p.left + p.right) / 2 for p in tv_patches]
    wire_centers = [(p.left + p.right) / 2 for p in wire_patches]

    for tv in tv_patches:
        for wire in wire_patches:
            if abs(tv_centers[tv_patches.index(tv)] - wire_centers[wire_patches.index(wire)]) < 10:
                return tv

    return tv_patches[0]

